export function renderPage(page, { siteUrl }) {
  const url = `${siteUrl}${page.path}`;
  const graph = [
    { '@type': 'Organization', '@id': `${siteUrl}/#organization`, name: company.name, url: siteUrl, logo: `${siteUrl}/assets/rekord-logo.png`, telephone: company.phone, email: company.email, sameAs: ['https://halenamiotowe.com.pl/', company.sourceUrl], contactPoint: { '@type': 'ContactPoint', telephone: company.phone, email: company.email, contactType: 'sales', areaServed: ['PL', 'EU'] }, areaServed: ['Polska', 'Unia Europejska'], address: { '@type': 'PostalAddress', streetAddress: company.address, addressLocality: company.city, postalCode: company.postalCode, addressCountry: 'PL' } },
    { '@type': 'WebSite', '@id': `${siteUrl}/#website`, name: 'Zasilimy', url: siteUrl, inLanguage: 'pl-PL', publisher: { '@id': `${siteUrl}/#organization` } },
    { '@type': page.series || page.active === 'catalog' ? 'CollectionPage' : 'WebPage', '@id': url, url, name: page.title, description: page.description, inLanguage: 'pl-PL', isPartOf: { '@id': `${siteUrl}/#website` } },
  ];
  if (page.crumbs) graph.push({ '@type': 'BreadcrumbList', itemListElement: [{ name: 'Strona główna', path: '/' }, ...page.crumbs].map((crumb, index) => ({ '@type': 'ListItem', position: index + 1, name: crumb.name, item: `${siteUrl}${crumb.path}` })) });
  if (page.active === 'catalog') graph.push({ '@type': 'ItemList', name: 'Agregaty prądotwórcze', itemListElement: equipment.map((item, index) => ({ '@type': 'ListItem', position: index + 1, name: item.name, url: `${siteUrl}${productPath(item)}` })) });
  if (['rental', 'sale'].includes(page.active)) graph.push({ '@type': 'Service', '@id': `${url}#service`, name: page.title, serviceType: `${page.active === 'rental' ? 'Wynajem' : 'Sprzedaż'} agregatów prądotwórczych`, provider: { '@id': `${siteUrl}/#organization` }, areaServed: ['Polska', 'Unia Europejska'], url });
  const jsonLd = JSON.stringify({ '@context': 'https://schema.org', '@graph': graph }).replace(/</g, '\\u003c');
  return `<!doctype html><html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#171a1c"><title>${e(page.title)}</title><meta name="description" content="${e(page.description)}">${page.noindex ? '<meta name="robots" content="noindex, follow">' : `<link rel="canonical" href="${e(url)}">`}<meta property="og:type" content="website"><meta property="og:locale" content="pl_PL"><meta property="og:site_name" content="Zasilimy"><meta property="og:title" content="${e(page.title)}"><meta property="og:description" content="${e(page.description)}"><meta property="og:url" content="${e(url)}"><meta property="og:image" content="${e(siteUrl)}/assets/generator-og.jpg"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Agregaty prądotwórcze SDMO KOHLER z oferty REKORD"><meta name="twitter:card" content="summary_large_image"><link rel="icon" type="image/svg+xml" href="/favicon.svg"><link rel="preload" href="/assets/barlow-condensed-600-latin.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="/assets/manrope-400-800-latin.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/styles.css"><script type="module" src="/app.js" onload="document.documentElement.classList.add('js')"></script><script type="application/ld+json">${jsonLd}</script></head><body class="page-${page.active}"><a class="skip-link" href="#main">Przejdź do treści</a>${header(page.active)}<main id="main">${page.render()}</main>${footer()}</body></html>`;
}
